function tournamentNow(){const d=new Date();return {date:d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"),mins:d.getHours()*60+d.getMinutes()}}
function matchState(time:string,done:boolean){if(done)return "final";const n=tournamentNow();if(n.date!=="2026-09-20")return "pending";const t=tournamentMinutes(time);return n.mins>=t&&n.mins<t+25?"live":n.mins>=t+25?"awaiting":"pending"}
function zoneFor(id:string,g:G,ms:Match[]){const tb=table(g,ms),row=tb.find(x=>x.id===id);if(!row)return null;if(complete(g,ms))return tb.findIndex(x=>x.id===id)<2?"oro":"plata";const others=tb.filter(x=>x.id!==id),left=(x:Row)=>3-x.pj,lo=row.pts,hi=row.pts+left(row)*3;const definitelyAbove=others.filter(x=>x.pts>hi).length,canReach=others.filter(x=>x.pts+left(x)*3>=lo).length;if(canReach<=1)return "oro";if(definitelyAbove>=2)return "plata";return null}
