function Groups({ms,initialGroup,clearGroup}:{ms:Match[];initialGroup:G|null;clearGroup:()=>void}){const [rules,setRules]=useState(false),[localGroup,setLocalGroup]=useState<G|null>(initialGroup);useEffect(()=>setLocalGroup(initialGroup),[initialGroup]);if(localGroup)return <GroupDetail g={localGroup} ms={ms} back={()=>{setLocalGroup(null);clearGroup()}}/>;return <div className="screen groups-screen"><div className="screen-title-row"><h2>Grupos</h2><button onClick={()=>setRules(true)} className="rules-link">Reglas</button></div>{rules&&<Rules onClose={()=>setRules(false)}/>}<div className="groups-grid">{(["A","B","C","D"] as G[]).map(g=><button key={g} className="group-box group-box-button" onClick={()=>setLocalGroup(g)}><div className="group-box-title">Grupo {g}{complete(g,ms)&&<span>✓</span>}</div>{table(g,ms).map((r,i)=><div className={"group-team zone-"+(i<2?"oro":"plata")} key={r.id}><b>{i+1}</b><img className={crestClass(r.id)} src={logo(r.id)} alt=""/><span>{T(r.id).name}</span><small>{i<2?"ORO":"PLATA"}</small><em>›</em></div>)}</button>)}</div></div>}
function GroupDetail({g,ms,back}:{g:G;ms:Match[];back:()=>void}){const[view,setView]=useState<"jornadas"|"clasificacion">("jornadas"),gm=ms.filter(m=>m.group===g).sort((a,b)=>a.time.localeCompare(b.time)),tb=table(g,ms),rounds=[gm.slice(0,2),gm.slice(2,4),gm.slice(4,6)];return <div className="screen group-detail"><div className="group-detail-head"><button onClick={back}>‹</button><div><small>FASE DE GRUPOS</small><h2>Grupo {g}</h2>{complete(g,ms)&&<b className="group-finished">✓ GRUPO FINALIZADO</b>}</div></div><div className="group-detail-tabs"><button className={view==="jornadas"?"active":""} onClick={()=>setView("jornadas")}>Jornadas</button><button className={view==="clasificacion"?"active":""} onClick={()=>setView("clasificacion")}>Clasificación</button></div>{view==="jornadas"?<div className="group-rounds">{rounds.map((round,i)=><section className="group-round" key={i}><div className="group-round-title"><b>JORNADA {i+1}</b><span>{round[0]?.time} · {round.length} partidos</span></div><div className="match-panel">{round.map(m=><MatchRow key={m.id} m={m}/>)}</div></section>)}</div>:<><div className="stand-card"><div className="stand-head"><span>#</span><span>EQUIPO</span><span>PTS</span><span>PJ</span><span>GF</span><span>GC</span><span>DG</span></div>{tb.map((r,i)=><div className="stand-row" key={r.id}><b className={"rank rank-"+(i+1)}>{i+1}</b><span><img className={crestClass(r.id)} src={logo(r.id)} alt=""/><strong>{T(r.id).name}</strong>{zoneFor(r.id,g,ms)&&<em className={"zone-badge "+zoneFor(r.id,g,ms)}>{zoneFor(r.id,g,ms)==="oro"?"ORO ✓":"PLATA ✓"}</em>}</span><b>{r.pts}</b><small>{r.pj}</small><small>{r.gf}</small><small>{r.gc}</small><small>{r.dg}</small></div>)}</div><div className="stand-legend"><span><i className="gold-dot"/>Fase Oro</span><span><i className="silver-dot"/>Fase Plata</span></div></>}</div>}

function MatchRow({m}:{m:Match}){const st=matchState(m.time,m.hs!==null);return <div className={"match-row "+(m.hs!==null?"played":"pending")+" "+st}><div className="match-team home"><span>{T(m.home).name}</span><img className={crestClass(m.home)} src={logo(m.home)} alt=""/></div><div className="match-score">{m.hs!==null?<><b>{m.hs} <i>–</i> {m.as}</b><small>FINAL</small></>:st==="live"?<><b className="live-label"><i/> EN JUEGO</b><small>{m.time} · CAMPO {m.field}</small></>:st==="awaiting"?<><b>{m.time}</b><small>RESULTADO PENDIENTE</small></>:<><b>{m.time}</b><small>CAMPO {m.field}</small></>}</div><div className="match-team away"><img className={crestClass(m.away)} src={logo(m.away)} alt=""/><span>{T(m.away).name}</span></div></div>}
function seed(code:string,ms:Match[]){const g=code[0] as G,n=Number(code[1]);if(!complete(g,ms))return null;return table(g,ms)[n-1]?.id||null}
function KO({kind,ms,results}:{kind:"Oro"|"Plata";ms:Match[];results:Record<string,ResultRow>}){const games=knockout(kind,ms,results);const champ=koWinner(games.find(x=>x.round==="FINAL")!);return <div className="screen ko-screen"><div className={"ko-title "+kind.toLowerCase()}><img className="official-cup-logo small" src="/logo%20derio%20cup.png" alt="Derio Cup"/><div><small>FASE</small><h2>{kind.toUpperCase()}</h2></div></div>{champ&&<div className={"phase-champion "+kind.toLowerCase()}><small>CAMPEÓN FASE {kind.toUpperCase()}</small><img src={logo(champ)} alt=""/><b>{T(champ).name}</b></div>}<KnockoutViews games={games} kind={kind}><div className="ko-bracket">{(["CF","SF","FINAL"] as const).map(round=><div key={round}><div className={"ko-section-title "+(round==="FINAL"?"final":"")}>{round==="CF"?"CUARTOS DE FINAL":round==="SF"?"SEMIFINALES":"FINAL"} <span>CAMPO {kind==="Oro"?1:2}</span></div><div className="ko-list">{games.filter(g=>g.round===round).map(g=><KOGameRow key={g.id} g={g}/>)}</div></div>)}</div></KnockoutViews></div>}
function KOGameRow({g}:{g:KOGame}){const r=g.result,valid=r&&r.home_team===g.home&&r.away_team===g.away;return <div className="ko-match"><div className="ko-time"><b>{g.time}</b><small>Campo {g.field}</small></div><div className="ko-code">{g.code}</div><div className="ko-team">{g.home&&<img className={crestClass(g.home)} src={logo(g.home)} alt=""/>}<span>{g.home?T(g.home).name:g.homeLabel}</span></div><strong>{valid?<span className="ko-result">{r!.home_score}{r!.home_score===r!.away_score&&r!.home_penalties!=null?<small> ({r!.home_penalties})</small>:null} – {r!.away_score}{r!.home_score===r!.away_score&&r!.away_penalties!=null?<small> ({r!.away_penalties})</small>:null}</span>:"–"}</strong><div className="ko-team away"><span>{g.away?T(g.away).name:g.awayLabel}</span>{g.away&&<img className={crestClass(g.away)} src={logo(g.away)} alt=""/>}</div></div>}
function Mine({id,ms,koResults}:{id:string;ms:Match[];koResults:Record<string,ResultRow>}){const t=T(id),own=ms.filter(m=>m.home===id||m.away===id),kos=(["Oro","Plata"] as const).flatMap(k=>knockout(k,ms,koResults)).filter(g=>g.home===id||g.away===id),tb=table(t.group,ms),pos=tb.findIndex(x=>x.id===id)+1;return <div className="screen mine-screen"><div className="team-hero"><img className={crestClass(id)} src={logo(id)} alt=""/><h2>{t.name}</h2><p>BENJAMÍN 2017 · GRUPO {t.group}</p></div><div className="team-summary"><div><small>GRUPO</small><b>{t.group}</b></div><div><small>POSICIÓN</small><b>{pos}º</b></div><div><small>PARTIDOS</small><b>{own.filter(x=>x.hs!==null).length+kos.filter(x=>validKO(x)).length}</b></div></div><h3>PARTIDOS</h3><div className="match-panel">{own.map(m=><MatchRow key={m.id} m={m}/>)}</div>{kos.length>0&&<><h3>FASE FINAL</h3><div className="ko-list">{kos.map(g=><KOGameRow key={g.id} g={g}/>)}</div></>}</div>}
function Rules({onClose}:{onClose:()=>void}){return <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/60 p-0 sm:items-center sm:p-4"><div className="w-full max-w-lg rounded-t-[28px] bg-[#202020] p-6 text-white sm:rounded-[28px]"><div className="flex items-center justify-between"><h3 className="text-xl font-black">REGLAS DE CLASIFICACIÓN</h3><button onClick={onClose} className="text-4xl font-light">×</button></div><div className="mt-8 space-y-2 text-base"><p>1. Puntos - Total</p><p>2. Puntos - Partidos directos</p><p>3. Diferencia de goles - Partidos directos</p><p>4. Goles a favor - Partidos directos</p><p>5. Diferencia de goles - Total</p><p>6. Goles a favor - Total</p><p>7. Tanda de penaltis</p></div><button onClick={onClose} className="mt-8 w-full rounded-full bg-amber-400 py-4 text-xl font-black text-black">OK</button></div></div>}

function TrophyMark({small=false}:{small?:boolean}){return <svg className={small?"trophy-mark small":"trophy-mark"} viewBox="0 0 180 180" fill="none" aria-hidden="true"><path d="M48 30H132V82C132 111 114 129 90 129S48 111 48 82V30Z" stroke="currentColor" strokeWidth="8" strokeLinejoin="round"/><path d="M48 49H28V70C28 88 37 98 52 98M132 49H152V70C152 88 143 98 128 98" stroke="currentColor" strokeWidth="8" strokeLinecap="round" strokeLinejoin="round"/><circle cx="90" cy="76" r="29" stroke="currentColor" strokeWidth="7"/><path d="M76 62V88M90 58V94M104 62V88M76 62H104" stroke="currentColor" strokeWidth="5" strokeLinecap="round"/><path d="M84 129V143H69V153H111V143H96V129M61 153H119L125 168H55L61 153Z" stroke="currentColor" strokeWidth="7" strokeLinejoin="round"/></svg>}

function PhaseIcon({type}:{type:"groups"|"gold"|"silver"}){if(type==="groups")return <svg className="phase-icon groups" viewBox="0 0 32 32"><circle cx="10" cy="10" r="4"/><circle cx="22" cy="10" r="4"/><circle cx="10" cy="22" r="4"/><circle cx="22" cy="22" r="4"/><path d="M14 10h4M10 14v4M22 14v4M14 22h4"/></svg>;return <svg className={"phase-icon "+type} viewBox="0 0 32 32"><path d="M9 5h14v7c0 5-3 8-7 8s-7-3-7-8V5Z"/><path d="M9 8H5v3c0 4 2 6 5 6M23 8h4v3c0 4-2 6-5 6M16 20v4M11 27h10M13 24h6"/></svg>}

function TeamCelebration({id}:{id:string}){const[colors,setColors]=useState(["#e32636","#1b75d0","#ffffff"]);useEffect(()=>{const img=new Image();img.src=logo(id);img.onload=()=>{try{const cv=document.createElement("canvas");cv.width=cv.height=48;const x=cv.getContext("2d",{willReadFrequently:true});if(!x)return;x.drawImage(img,0,0,48,48);const d=x.getImageData(0,0,48,48).data,bins=new Map<string,number>();for(let i=0;i<d.length;i+=16){if(d[i+3]<100)continue;const r=d[i],g=d[i+1],b=d[i+2];if(r>242&&g>242&&b>242)continue;if(r<18&&g<18&&b<18)continue;const key=[r,g,b].map(v=>Math.round(v/40)*40).join(",");bins.set(key,(bins.get(key)||0)+1)}const picked=[...bins.entries()].sort((a,b)=>b[1]-a[1]).slice(0,3).map(([k])=>"rgb("+k+")");if(picked.length)setColors(picked)}catch{}}},[id]);const bursts=[{x:14,y:22,d:.02},{x:84,y:20,d:.22},{x:49,y:12,d:.43},{x:27,y:49,d:.64},{x:74,y:47,d:.84},{x:15,y:79,d:1.04},{x:84,y:78,d:1.24},{x:50,y:90,d:1.45}];return <div className="team-celebration" aria-live="polite"><div className="fireworks-canvas" aria-hidden="true">{bursts.map((b,i)=><span key={i} className="fw-burst" style={{left:b.x+"%",top:b.y+"%",animationDelay:b.d+"s","--fw":colors[i%colors.length],"--fw2":colors[(i+1)%colors.length]} as CSSProperties}/>)}</div><div className="team-celebration-card" style={{"--team-a":colors[0],"--team-b":colors[1]||colors[0]} as CSSProperties}><small>EQUIPO SELECCIONADO</small><img className={crestClass(id)} src={logo(id)} alt=""/><h2>{T(id).name}</h2><strong>Aupa {T(id).name}!!</strong><span>Zorte on!</span></div></div>}

function TournamentFinished({oro,plata}:{oro:KOGame;plata:KOGame}){const ow=koWinner(oro)!,pw=koWinner(plata)!,orunner=oro.home===ow?oro.away:oro.home,prunner=plata.home===pw?plata.away:plata.home;const score=(g:KOGame)=>{const r=g.result!;return r.home_score+"–"+r.away_score+(r.home_penalties!=null?" ("+r.home_penalties+"–"+r.away_penalties+" pen.)":"")};return <section className="tournament-finished"><small>DERIO CUP · FINALIZADA</small><h3>Resultados finales</h3><div className="podium-grid"><span><b>CAMPEÓN ORO</b><img src={logo(ow)} alt=""/><strong>{T(ow).name}</strong></span><span><b>SUBCAMPEÓN ORO</b>{orunner&&<img src={logo(orunner)} alt=""/>}<strong>{orunner?T(orunner).name:"—"}</strong></span><span><b>CAMPEÓN PLATA</b><img src={logo(pw)} alt=""/><strong>{T(pw).name}</strong></span><span><b>SUBCAMPEÓN PLATA</b>{prunner&&<img src={logo(prunner)} alt=""/>}<strong>{prunner?T(prunner).name:"—"}</strong></span></div><div className="final-results"><b>FINAL ORO · {score(oro)}</b><span>{T(oro.home!).name} – {T(oro.away!).name}</span><b>FINAL PLATA · {score(plata)}</b><span>{T(plata.home!).name} – {T(plata.away!).name}</span></div></section>}

function Dashboard({ms,selected,go,openGroup,koResults,fanCounts}:{ms:Match[];selected:string;fanCounts:Record<string,number>;go:(x:"inicio"|"partidos"|"clasificacion"|"mas"|"grupos"|"oro"|"plata"|"mi")=>void;openGroup:(g:G)=>void;koResults:Record<string,ResultRow>}){const[phase,setPhase]=useState<"grupos"|"oro"|"plata"|"mi">("grupos"),neutral=selected==="neutral",oro=knockout("Oro",ms,koResults),plata=knockout("Plata",ms,koResults),now=tournamentNow(),live=ms.filter(m=>matchState(m.time,m.hs!==null)==="live"),pending=ms.filter(m=>m.hs===null).sort((a,b)=>a.time.localeCompare(b.time)),goldFinal=oro.find(x=>x.round==="FINAL")!,silverFinal=plata.find(x=>x.round==="FINAL")!,goldChamp=koWinner(goldFinal),silverChamp=koWinner(silverFinal),finished=!!goldChamp&&!!silverChamp;const phaseGames=phase==="oro"?oro:phase==="plata"?plata:[];return <div className="dashboard">
<div className="hero-brand"><img className="official-cup-logo" src="/logo%20derio%20cup.png" alt="Derio Cup"/><div className="hero-wordmark">DERIO <span>CUP</span></div><div className="hero-date">BENJAMÍN 2017 · 20 DE SEPTIEMBRE</div></div>
{finished?<TournamentFinished oro={goldFinal} plata={silverFinal}/>:live.length?<div className="now-playing"><b><i/> AHORA EN JUEGO</b><span>{live.length} {live.length===1?"partido":"partidos"}</span></div>:<div className="next-up"><small>{now.date==="2026-09-20"?"PRÓXIMAMENTE":"PRÓXIMOS PARTIDOS"}</small><b>{pending[0]?pending[0].time+" · "+T(pending[0].home).name+" – "+T(pending[0].away).name:"Fase de grupos finalizada"}</b></div>}
<div className={"phase-grid "+(neutral?"neutral":"")}>
<button className={"phase-card "+(phase==="grupos"?"active":"")} onClick={()=>setPhase("grupos")}><PhaseIcon type="groups"/><b>Fase de<br/>grupos</b></button>
<button className={"phase-card "+(phase==="oro"?"active":"")} onClick={()=>setPhase("oro")}><PhaseIcon type="gold"/><b>Fase<br/>Oro</b></button>
<button className={"phase-card "+(phase==="plata"?"active":"")} onClick={()=>setPhase("plata")}><PhaseIcon type="silver"/><b>Fase<br/>Plata</b></button>
{!neutral&&<button className={"phase-card "+(phase==="mi"?"active":"")} onClick={()=>setPhase("mi")}><img className={crestClass(selected)} src={logo(selected)} alt=""/><b>Mi<br/>equipo</b></button>}
</div>
<div className="home-phase-content" key={phase}>{phase==="grupos"?<><div className="tournament-status"><span className="live-dot"/><div><small>FASE DE GRUPOS</small><b>4 grupos · 16 equipos · 24 partidos</b></div><em>{ms.filter(m=>m.hs!==null).length}/24</em></div><div className="section-head"><b>GRUPOS</b><button onClick={()=>go("grupos")}>Ver todos ›</button></div><div className="group-preview">{(["A","B","C","D"] as G[]).map(g=><button key={g} aria-label={"Abrir Grupo "+g} onClick={()=>openGroup(g)}><b>Grupo {g} {complete(g,ms)&&"✓"}</b><div>{ids(g).map(id=><img key={id} className={crestClass(id)} src={logo(id)} alt={T(id).name}/>)}</div></button>)}</div><div className="section-head"><b>{live.length?"AHORA EN JUEGO":"PRÓXIMOS PARTIDOS"}</b><button onClick={()=>go("partidos")}>Ver calendario ›</button></div><div className="match-panel">{(live.length?live:pending).slice(0,4).map(m=><MatchRow key={m.id} m={m}/>)}</div></>:phase==="mi"&&!neutral?<><button className="my-team-strip" onClick={()=>go("mi")}><img className={crestClass(selected)} src={logo(selected)} alt=""/><div><small>MI EQUIPO</small><b>{T(selected).name}</b><em>Grupo {T(selected).group} · {table(T(selected).group,ms).findIndex(x=>x.id===selected)+1}.º</em></div><span>Ver equipo ›</span></button><div className="section-head"><b>MIS PARTIDOS</b><button onClick={()=>go("mi")}>Ver todos ›</button></div><div className="match-panel">{ms.filter(m=>m.home===selected||m.away===selected).map(m=><MatchRow key={m.id} m={m}/>)}</div></>:<><div className={"home-phase-banner "+phase}><div><small>FASE {phase.toUpperCase()}</small><b>{phase==="oro"?"1.º y 2.º de cada grupo":"3.º y 4.º de cada grupo"}</b></div><button onClick={()=>go(phase)}>Ver cuadro completo ›</button></div><div className="section-head"><b>CUADRO FINAL</b><button onClick={()=>go(phase)}>Ver fase ›</button></div><KnockoutViews games={phaseGames} kind={phase==="oro"?"Oro":"Plata"}><div className="ko-bracket-mini">{phaseGames.map(g=><KOGameRow key={g.id} g={g}/>)}</div></KnockoutViews></>}<FanRanking counts={fanCounts}/></div>
</div>}

function FanRanking({counts}:{counts:Record<string,number>}){const top=teams.slice().sort((a,b)=>(counts[b.id]||0)-(counts[a.id]||0)||a.name.localeCompare(b.name)).slice(0,3);return <section className="fan-ranking"><div className="fan-ranking-head"><div><small>AFICIÓN DERIO CUP</small><b>Equipos con más afición</b></div><span>TOP 3</span></div><div className="fan-ranking-list">{top.map((t,i)=><div className={"fan-rank fan-rank-"+(i+1)} key={t.id}><strong>{i+1}</strong><img className={crestClass(t.id)} src={logo(t.id)} alt=""/><div><b>{t.name}</b><small>{counts[t.id]||0} {(counts[t.id]||0)===1?"seguidor":"seguidores"}</small></div></div>)}</div><p>Se contabiliza el equipo seleccionado por cada usuario.</p></section>}

function AllMatches({ms,koResults,openGroup}:{ms:Match[];koResults:Record<string,ResultRow>;openGroup:(g:G)=>void}){const[filter,setFilter]=useState<"todos"|"grupos"|"oro"|"plata">("todos");return <div className="screen"><h2>Partidos</h2><div className="filter-row">{(["todos","grupos","oro","plata"] as const).map(x=><button key={x} className={filter===x?"active":""} onClick={()=>setFilter(x)}>{x==="todos"?"Todos":x==="grupos"?"Fase de grupos":x==="oro"?"Fase Oro":"Fase Plata"}</button>)}</div><h3>Sábado 20 de Septiembre</h3><div className="match-panel">{(filter==="todos"||filter==="grupos")&&ms.slice().sort((a,b)=>a.time.localeCompare(b.time)).map(m=><div className="match-with-group" key={m.id}><button className="match-group-link" onClick={()=>openGroup(m.group)} aria-label={"Abrir Grupo "+m.group}>GRUPO {m.group}<span>›</span></button><MatchRow m={m}/></div>)}</div>{(filter==="todos"||filter==="oro")&&<div className="ko-list all-ko">{knockout("Oro",ms,koResults).map(g=><KOGameRow key={g.id} g={g}/>)}</div>}{(filter==="todos"||filter==="plata")&&<div className="ko-list all-ko">{knockout("Plata",ms,koResults).map(g=><KOGameRow key={g.id} g={g}/>)}</div>}</div>}

function Standings({ms}:{ms:Match[]}){const[g,setG]=useState<G>("A");const tb=table(g,ms);return <div className="screen"><h2>Clasificación</h2><div className="group-tabs">{(["A","B","C","D"] as G[]).map(x=><button key={x} className={g===x?"active":""} onClick={()=>setG(x)}>Grupo {x}</button>)}</div><div className="stand-card"><div className="stand-head"><span>#</span><span>EQUIPO</span><span>PTS</span><span>PJ</span><span>GF</span><span>GC</span><span>DG</span></div>{tb.map((r,i)=><div className="stand-row" key={r.id}><b className={"rank rank-"+(i+1)}>{i+1}</b><span><img className={crestClass(r.id)} src={logo(r.id)} alt=""/><strong>{T(r.id).name}</strong>{zoneFor(r.id,g,ms)&&<em className={"zone-badge "+zoneFor(r.id,g,ms)}>{zoneFor(r.id,g,ms)==="oro"?"ORO ✓":"PLATA ✓"}</em>}</span><b>{r.pts}</b><small>{r.pj}</small><small>{r.gf}</small><small>{r.gc}</small><small>{r.dg}</small></div>)}</div><div className="stand-legend"><span><i className="gold-dot"/>Fase Oro</span><span><i className="silver-dot"/>Fase Plata</span></div></div>}

function More({ms,koResults,setKoResults,scores,setScores,changeTeam}:{ms:Match[];koResults:Record<string,ResultRow>;setKoResults:(x:Record<string,ResultRow>)=>void;scores:Record<string,[number,number]>;setScores:(x:Record<string,[number,number]>)=>void;changeTeam:()=>void}){const[info,setInfo]=useState<string|null>(null);const[manager,setManager]=useState(false);const items=[["Información del torneo","info"],["Ubicación · Ibaiondo","pin"],["Formato del torneo","trophy"],["Normas de juego","ball"],["Comidas y bar","coffee"]];return <div className="screen more-screen"><h2>Información</h2><p className="more-intro">Todo lo necesario para el día del torneo.</p><div className="more-card">{items.map(([x,ic])=><button key={x} onClick={()=>setInfo(x)}><span><InfoMenuIcon icon={ic}/></span><div><b>{x}</b><small>{x==="Ubicación · Ibaiondo"?"Instalaciones Deportivas de Ibaiondo":x==="Formato del torneo"?"Grupos, fases finales y desempates":x==="Normas de juego"?"Reglas específicas Derio Cup":x==="Comidas y bar"?"Servicios durante todo el torneo":"20 de septiembre · Benjamín 2017"}</small></div><em>›</em></button>)}<button onClick={()=>setManager(true)}><span><InfoMenuIcon icon="lock"/></span><div><b>Acceso Responsables Torneo</b><small>Gestión y publicación de resultados</small></div><em>›</em></button><button onClick={changeTeam}><span><InfoMenuIcon icon="switch"/></span><div><b>Cambiar de equipo</b><small>Seleccionar otro participante</small></div><em>›</em></button></div>{manager&&<Manager ms={ms} koResults={koResults} setKoResults={setKoResults} scores={scores} setScores={setScores} onClose={()=>setManager(false)}/>} {info&&<InfoDialog title={info} onClose={()=>setInfo(null)}>{info==="Información del torneo"?<div className="info-content"><p>Derio Cup es un torneo de fútbol base organizado por el CD Derio para la categoría Benjamín 2017, temporada 2026/27.</p><div className="info-chips"><span>16 equipos</span><span>20 septiembre</span><span>Ibaiondo</span></div></div>:info==="Ubicación · Ibaiondo"?<div className="info-content"><p>El torneo se disputa en las <b>Instalaciones Deportivas de Ibaiondo, Derio</b>.</p><a className="map-button" href="https://maps.app.goo.gl/q2zy9gfVQ1dPcaqS6" target="_blank" rel="noreferrer">⌖ Abrir ubicación en Maps</a><p className="muted">Los encuentros se reparten entre Campo 1 y Campo 2 según el calendario.</p></div>:info==="Formato del torneo"?<div className="info-content"><div className="rule-highlight"><b>20 minutos</b><span>Todos los partidos · sin descanso</span></div><p>Fase de grupos y dos fases finales: <b>Fase Oro</b> y <b>Fase Plata</b>. Victoria: 3 puntos · empate: 1 · derrota: 0.</p><p>Los cambios son <b>ilimitados</b> durante todo el partido.</p><p>En las fases finales, si hay empate se lanzan <b>3 penaltis por equipo</b>. Solo pueden lanzar inicialmente los 7 jugadores que hayan terminado el encuentro y debe mantenerse el portero que lo haya finalizado. Si continúa el empate, podrán lanzar los jugadores del banquillo.</p><h4>Desempates de grupo</h4><ol><li>Puntos totales</li><li>Puntos en partidos directos</li><li>Diferencia de goles en partidos directos</li><li>Goles a favor en partidos directos</li><li>Diferencia de goles total</li><li>Goles a favor total</li><li>Tanda de penaltis</li></ol></div>:info==="Normas de juego"?<div className="info-content"><p>El equipo designado como <b>visitante</b> deberá cambiar de equipación si existe coincidencia. Es obligatorio acudir con segunda equipación.</p><p>Fuera de juego desde la línea de 13 m. El área de penalti es el área pequeña delimitada.</p><p>La cesión al portero se sanciona con falta directa desde la línea de 13 m, sin barrera. <b>Todas las faltas son directas.</b></p><p>Cada equipo debe traer sus propios balones para calentar.</p><div className="warning-box">Las conductas antideportivas pueden suponer la eliminación por decisión de la organización.</div></div>:<div className="info-content"><p>Los equipos participantes disponen de servicio de comidas opcional en Ibaiondo por <b>8 €</b>.</p><p>Incluye hamaiketako, plato de pasta, pan, agua y postre.</p><p>Para las familias habrá servicio de bar con pintxos y bocadillos durante todo el torneo.</p></div>}</InfoDialog>}<div className="more-brand"><img className="official-cup-logo small" src="/logo%20derio%20cup.png" alt="Derio Cup"/><div className="hero-wordmark">DERIO <span>CUP</span></div><small>BENJAMIN 2017</small></div></div>}

function Manager({ms,koResults,setKoResults,scores,setScores,onClose}:{ms:Match[];koResults:Record<string,ResultRow>;setKoResults:(x:Record<string,ResultRow>)=>void;scores:Record<string,[number,number]>;setScores:(x:Record<string,[number,number]>)=>void;onClose:()=>void}){const[code,setCode]=useState(()=>typeof window!=="undefined"&&localStorage.getItem("derio-cup-manager-auth-v2")==="1802"?"1802":""),[ok,setOk]=useState(()=>typeof window!=="undefined"&&localStorage.getItem("derio-cup-manager-auth-v2")==="1802"),[err,setErr]=useState(""),[saving,setSaving]=useState<string|null>(null),[saved,setSaved]=useState<string|null>(null),[undo,setUndo]=useState<{payload:any;previous:any}|null>(null);const remove=async(match_id:string)=>{if(!confirm("¿Eliminar este resultado?"))return;setSaving(match_id);setErr("");try{const r=await fetch(SB_URL+"/rest/v1/rpc/delete_derio_cup_result",{method:"POST",headers:{"Content-Type":"application/json",apikey:SB_KEY},body:JSON.stringify({p_match_id:match_id})});if(!r.ok){const j=await r.json();throw new Error(j.message||j.error||"No se pudo eliminar")}if(match_id.startsWith("grupo-")){const n={...scores};delete n[match_id];setScores(n)}else{const n={...koResults};delete n[match_id];setKoResults(n)}}catch(e){setErr(e instanceof Error?e.message:"No se pudo eliminar")}finally{setSaving(null)}};const save=async(payload:any)=>{const previous=payload.match_id.startsWith("grupo-")?scores[payload.match_id]:koResults[payload.match_id];setSaving(payload.match_id);setErr("");try{const r=await fetch(SB_URL+"/functions/v1/derio-cup-result",{method:"POST",headers:{"Content-Type":"application/json",apikey:SB_KEY},body:JSON.stringify({...payload,code})});const j=await r.json();if(!r.ok)throw new Error(j.error||"No se pudo guardar");if(payload.match_id.startsWith("grupo-"))setScores({...scores,[payload.match_id]:[payload.home_score,payload.away_score]});else setKoResults({...koResults,[payload.match_id]:j[0]||{...payload,updated_at:new Date().toISOString()}});setSaved(payload.match_id);setUndo({payload,previous});const undoId=payload.match_id;setTimeout(()=>setSaved(null),8000);setTimeout(()=>setUndo(null),8000)}catch(e){setErr(e instanceof Error?e.message:"No se pudo guardar")}finally{setSaving(null)}};const undoSave=async()=>{if(!undo)return;const {payload,previous}=undo;setSaving(payload.match_id);setErr("");try{if(previous){const restore=payload.match_id.startsWith("grupo-")?{...payload,home_score:previous[0],away_score:previous[1]}:{...previous,code};const r=await fetch(SB_URL+"/functions/v1/derio-cup-result",{method:"POST",headers:{"Content-Type":"application/json",apikey:SB_KEY},body:JSON.stringify({...restore,code})});if(!r.ok)throw new Error("No se pudo deshacer");if(payload.match_id.startsWith("grupo-"))setScores({...scores,[payload.match_id]:previous});else setKoResults({...koResults,[payload.match_id]:previous}) }else{const r=await fetch(SB_URL+"/rest/v1/rpc/delete_derio_cup_result",{method:"POST",headers:{"Content-Type":"application/json",apikey:SB_KEY},body:JSON.stringify({p_match_id:payload.match_id})});if(!r.ok)throw new Error("No se pudo deshacer");if(payload.match_id.startsWith("grupo-")){const n={...scores};delete n[payload.match_id];setScores(n)}else{const n={...koResults};delete n[payload.match_id];setKoResults(n)}}setUndo(null);setSaved(null)}catch(e){setErr(e instanceof Error?e.message:"No se pudo deshacer")}finally{setSaving(null)}};const games=(["Oro","Plata"] as const).flatMap(k=>knockout(k,ms,koResults)).sort((a,b)=>a.time.localeCompare(b.time)||a.field-b.field);return <div className="info-modal manager-modal" onClick={onClose}><div className="info-sheet manager-sheet" onClick={e=>e.stopPropagation()}><button className="info-close" onClick={onClose}>×</button><h3>{ok?"Gestión de resultados":"Acceso Responsables Torneo"}</h3>{!ok?<form className="manager-login" onSubmit={e=>{e.preventDefault();if(code==="1802"){localStorage.removeItem("derio-cup-manager-auth");localStorage.removeItem("derio-cup-manager-code");localStorage.setItem("derio-cup-manager-auth-v2","1802");setOk(true);setErr("")}else setErr("Código incorrecto")}}><p>Introduce el código de acceso para gestionar los resultados del torneo.</p><input type="tel" inputMode="numeric" autoComplete="off" maxLength={4} value={code} onChange={e=>{const v=e.currentTarget.value.replace(/[^0-9]/g,"").slice(0,4);setCode(v)}} placeholder="Código de acceso"/><button>Acceder</button>{err&&<small className="manager-error">{err}</small>}</form>:<div className="manager-results">{saved&&<div className="save-toast"><span>✓ Resultado publicado</span>{undo&&<button onClick={undoSave}>DESHACER</button>}</div>}<div className="manager-ok">● ACCESO RESPONSABLE</div><div className="manager-guide"><b>Resultados del torneo</b><span>Introduce los goles de cada equipo y pulsa Guardar. Los partidos están ordenados por hora.</span></div><div className="manager-progress"><b>{Object.keys(scores).length}/24 resultados de grupos</b><span>{24-Object.keys(scores).length} pendientes</span></div><h4>FASE DE GRUPOS · ORDEN POR HORA</h4>{ms.slice().sort((a,b)=>a.time.localeCompare(b.time)).map(m=><ManagerMatch key={m.id} m={m} current={scores[m.id]} saving={saving===m.id} save={save} remove={remove}/>) }<h4>FASES FINALES · ORDEN POR HORA</h4>{games.map(g=><ManagerKO key={g.id} g={g} saving={saving===g.id} save={save} remove={remove}/>)}{err&&<small className="manager-error">{err}</small>}</div>}</div></div>}
function ManagerMatch({m,current,saving,save,remove}:{m:Match;current?:[number,number];saving:boolean;save:(p:any)=>void;remove:(id:string)=>void}){const[h,setH]=useState(current?.[0]?.toString()||""),[a,setA]=useState(current?.[1]?.toString()||"");useEffect(()=>{setH(current?.[0]?.toString()||"");setA(current?.[1]?.toString()||"")},[current]);return <div className="manager-match"><div className="manager-match-meta"><div><small>GRUPO {m.group}</small><b>{m.time}</b></div><span className="manager-field">CAMPO {m.field}</span></div><div className="manager-score-team"><img className={crestClass(m.home)} src={logo(m.home)} alt=""/><span><small>LOCAL</small>{T(m.home).name}</span><input type="number" min="0" value={h} onChange={e=>setH(e.target.value)}/></div><div className="manager-score-team"><img className={crestClass(m.away)} src={logo(m.away)} alt=""/><span><small>VISITANTE</small>{T(m.away).name}</span><input type="number" min="0" value={a} onChange={e=>setA(e.target.value)}/></div><button disabled={saving||h===""||a===""} onClick={()=>save({match_id:m.id,home_score:Number(h),away_score:Number(a),home_team:m.home,away_team:m.away,phase:"group",round:"group"})}>{saving?"Guardando…":current?"Editar":"Guardar"}</button>{current&&<button className="manager-delete" disabled={saving} onClick={()=>remove(m.id)}>Eliminar resultado</button>}</div>}
function ManagerKO({g,saving,save,remove}:{g:KOGame;saving:boolean;save:(p:any)=>void;remove:(id:string)=>void}){const r=g.result,valid=r&&r.home_team===g.home&&r.away_team===g.away,[h,setH]=useState(valid?String(r!.home_score):""),[a,setA]=useState(valid?String(r!.away_score):""),[hp,setHp]=useState(valid&&r!.home_penalties!=null?String(r!.home_penalties):""),[ap,setAp]=useState(valid&&r!.away_penalties!=null?String(r!.away_penalties):"");useEffect(()=>{setH(valid?String(r!.home_score):"");setA(valid?String(r!.away_score):"");setHp(valid&&r!.home_penalties!=null?String(r!.home_penalties):"");setAp(valid&&r!.away_penalties!=null?String(r!.away_penalties):"")},[g.home,g.away,r?.updated_at]);const tie=h!==""&&a!==""&&Number(h)===Number(a);return <div className={"manager-match manager-ko "+(!g.home||!g.away?"locked":"")}><div className="manager-match-meta"><div><small>{g.kind.toUpperCase()} · {g.code}</small><b>{g.time}</b></div><span className="manager-field">CAMPO {g.field} · {g.round==="CF"?"CUARTOS":g.round==="SF"?"SEMIFINAL":"FINAL"}</span></div><div className="manager-score-team">{g.home&&<img className={crestClass(g.home)} src={logo(g.home)} alt=""/>}<span><small>LOCAL</small>{g.home?T(g.home).name:g.homeLabel}</span><input disabled={!g.home} type="number" min="0" value={h} onChange={e=>setH(e.target.value)}/></div><div className="manager-score-team">{g.away&&<img className={crestClass(g.away)} src={logo(g.away)} alt=""/>}<span><small>VISITANTE</small>{g.away?T(g.away).name:g.awayLabel}</span><input disabled={!g.away} type="number" min="0" value={a} onChange={e=>setA(e.target.value)}/></div>{tie&&<div className="penalty-inputs"><b>PENALTIS</b><input type="number" min="0" value={hp} onChange={e=>setHp(e.target.value)}/><span>–</span><input type="number" min="0" value={ap} onChange={e=>setAp(e.target.value)}/></div>}<button disabled={saving||!g.home||!g.away||h===""||a===""||(tie&&(hp===""||ap===""||hp===ap))} onClick={()=>save({match_id:g.id,home_score:Number(h),away_score:Number(a),home_penalties:tie?Number(hp):null,away_penalties:tie?Number(ap):null,home_team:g.home,away_team:g.away,phase:g.kind.toLowerCase(),round:g.round.toLowerCase()})}>{saving?"Guardando…":valid?"Editar":"Guardar"}</button>{valid&&<button className="manager-delete" disabled={saving} onClick={()=>remove(g.id)}>Eliminar resultado</button>}</div>}


function NavBtn({label,active,onClick,icon}:{label:string;active:boolean;onClick:()=>void;icon:string}){const path=icon==="home"?"M3 11 12 4l9 7v9h-6v-6H9v6H3Z":icon==="cup"?"M7 4h10v5a5 5 0 0 1-10 0V4Zm5 10v4m-4 2h8":icon==="bars"?"M5 20v-6m7 6V8m7 12V4":"M5 12h.01M12 12h.01M19 12h.01";return <button className={active?"active":""} onClick={onClick}>{icon==="ball"?<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m12 7 4.75 3.45-1.82 5.59H9.07l-1.82-5.59L12 7Zm0 0V3m4.75 7.45 3.81-1.23m-5.63 6.82 2.36 3.24m-8.22-3.24-2.36 3.24m.54-8.83L3.44 9.22"/></svg>:<svg viewBox="0 0 24 24"><path d={path}/></svg>}<span>{label}</span></button>}
function Splash(){return <div className="splash fixed inset-0 z-[100] overflow-hidden text-white"><div className="smoke smoke-red"/><div className="smoke smoke-blue"/><div className="splash-center"><img className="official-cup-logo" src="/logo%20derio%20cup.png" alt="Derio Cup"/><div className="splash-title">DERIO CUP</div><div className="splash-sub">BENJAMIN 2017 • 20 DE SEPTIEMBRE</div></div><div className="splash-load"><div className="splash-line"/><small>CARGANDO...</small></div></div>}

function KnockoutViews({games,kind,children}:{games:KOGame[];kind:"Oro"|"Plata";children:React.ReactNode}){
 const[view,setView]=useState<"list"|"bracket">("list");
 return <div className="dc-knockout-views">
 <div className="dc-bracket-toggle" role="group" aria-label={"Vista de Fase "+kind}>
 <button type="button" aria-pressed={view==="list"} onClick={()=>setView("list")}>Lista</button>
 <button type="button" aria-pressed={view==="bracket"} onClick={()=>setView("bracket")}>Cuadro de eliminatorias</button>
 </div>
 {view==="list"?children:<><p className="dc-bracket-hint">Desliza para ver el camino hasta la final. Los equipos avanzan automáticamente con los resultados.</p><div className={"dc-bracket-scroll "+kind.toLowerCase()} tabIndex={0} role="region" aria-label={"Cuadro de eliminatorias de Fase "+kind}>
 <div className="dc-bracket-head"><b>CUARTOS DE FINAL</b><b>SEMIFINALES</b><b>FINAL</b></div>
 <div className="dc-bracket-canvas">
 <svg className="dc-bracket-lines" viewBox="0 0 808 560" aria-hidden="true"><path d="M240 70H262V210H240 M262 140H284 M240 350H262V490H240 M262 420H284 M524 140H546V420H524 M546 280H568"/></svg>
 {games.filter(g=>g.round==="CF").sort((a,b)=>["CF1","CF3","CF2","CF4"].indexOf(a.code)-["CF1","CF3","CF2","CF4"].indexOf(b.code)).map((g,i)=><BracketGame key={g.id} game={g} x={0} y={10+i*140}/>)}
 {games.filter(g=>g.round==="SF").map((g,i)=><BracketGame key={g.id} game={g} x={284} y={80+i*280}/>)}
 {games.filter(g=>g.round==="FINAL").map(g=><BracketGame key={g.id} game={g} x={568} y={220}/>)}
 </div></div></>}
 </div>
}
function BracketGame({game:g,x,y}:{game:KOGame;x:number;y:number}){
 const valid=validKO(g),r=valid?g.result:undefined,winner=koWinner(g);
 return <article className={"dc-bracket-game"+(g.round==="FINAL"?" dc-bracket-final":"")} style={{left:x,top:y}} aria-label={g.code+", "+g.time+", Campo "+g.field}>
 <header><b>{g.code}</b><span>{g.time} · Campo {g.field}</span></header>
 {([{id:g.home,label:g.homeLabel,score:r?.home_score,pen:r?.home_penalties},{id:g.away,label:g.awayLabel,score:r?.away_score,pen:r?.away_penalties}]).map((t,i)=><div key={i} className={"dc-bracket-team"+(t.id&&winner===t.id?" is-winner":"")}>
 <span className="dc-bracket-crest">{t.id?<img className={crestClass(t.id)} src={logo(t.id)} alt=""/>:<span>—</span>}</span>
 <span className="dc-bracket-name">{t.id?T(t.id).name:t.label}</span>
 <strong>{t.score??"–"}{r&&r.home_score===r.away_score&&t.pen!=null&&<small> ({t.pen})</small>}</strong>
 </div>)}
 </article>
}

