 ball:"m12 7 4.75 3.45-1.82 5.59H9.07l-1.82-5.59L12 7Zm0 0V3m4.75 7.45 3.81-1.23m-5.63 6.82 2.36 3.24m-8.22-3.24-2.36 3.24m.54-8.83L3.44 9.22",
 coffee:"M4 8h12v7a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V8Zm12 1h2a3 3 0 0 1 0 6h-2M3 22h16M7 2v2m4-2v2m4-2v2",
