function InfoDialog({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){
 const dialog=useRef<HTMLDialogElement>(null),timer=useRef<ReturnType<typeof setTimeout>|null>(null);
 const[closing,setClosing]=useState(false);
 useEffect(()=>{
  const el=dialog.current,previous=document.activeElement as HTMLElement|null;
  const overflow=document.body.style.overflow;
  document.body.style.overflow="hidden";
  el?.showModal();
  return()=>{if(timer.current)clearTimeout(timer.current);el?.close();document.body.style.overflow=overflow;if(previous?.isConnected)previous.focus()};
 },[]);
 function close(){
  if(timer.current)return;
  setClosing(true);
  timer.current=setTimeout(onClose,window.matchMedia("(prefers-reduced-motion: reduce)").matches?0:200);
 }
 return <dialog ref={dialog} className={"dc-info-dialog"+(closing?" is-closing":"")} aria-label={title} onCancel={e=>{e.preventDefault();close()}} onClick={e=>{if(e.target===e.currentTarget)close()}}>
 <section className="dc-info-panel">
 <header><h3>{title}</h3><button type="button" autoFocus aria-label="Cerrar información" onClick={close}><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6"/></svg></button></header>
 <div className="dc-info-body">{children}</div>
 </section>
 </dialog>
}
